"""Image preview/export node with native-aspect previews and no padding."""

from __future__ import annotations

import os
from typing import Any

import numpy as np
import torch
from PIL import Image

import folder_paths


PREVIEW_FORMATS = ("png", "jpg", "webp")
PREVIEW_ALIGNMENT = 8


def _preview_image_to_pil(image: torch.Tensor) -> Image.Image:
    """Convert one ComfyUI IMAGE frame to an RGB PIL image."""
    if not isinstance(image, torch.Tensor) or image.ndim != 3:
        raise ValueError("输入必须是 IMAGE 张量")
    array = image.detach().to(device="cpu", dtype=torch.float32).clamp(0.0, 1.0)
    array = (array.mul(255.0).round().to(torch.uint8).numpy())
    channels = array.shape[-1]
    if channels == 1:
        return Image.fromarray(array[:, :, 0], mode="L").convert("RGB")
    if channels == 4:
        return Image.fromarray(array, mode="RGBA")
    if channels < 3:
        raise ValueError("IMAGE 至少需要 1 个颜色通道")
    return Image.fromarray(array[:, :, :3], mode="RGB")


def _preview_target_size(width: int, height: int, longest_edge: int) -> tuple[int, int]:
    """Return an aspect-preserving size aligned to the hidden 8-pixel grid."""
    width = max(int(width), 1)
    height = max(int(height), 1)
    longest_edge = int(longest_edge or 0)
    if longest_edge <= 0:
        return width, height

    scale = longest_edge / max(width, height)
    target_width = max(1, int(round(width * scale)))
    target_height = max(1, int(round(height * scale)))
    # Round up so a requested longest edge is never made smaller by alignment.
    target_width = max(PREVIEW_ALIGNMENT, ((target_width + PREVIEW_ALIGNMENT - 1) // PREVIEW_ALIGNMENT) * PREVIEW_ALIGNMENT)
    target_height = max(PREVIEW_ALIGNMENT, ((target_height + PREVIEW_ALIGNMENT - 1) // PREVIEW_ALIGNMENT) * PREVIEW_ALIGNMENT)
    return target_width, target_height


def _preview_resize(image: Image.Image, longest_edge: int) -> Image.Image:
    target_width, target_height = _preview_target_size(*image.size, longest_edge)
    if image.size == (target_width, target_height):
        return image
    return image.resize((target_width, target_height), Image.LANCZOS)


def _preview_pil_to_tensor(image: Image.Image) -> torch.Tensor:
    array = np.asarray(image.convert("RGB"), dtype=np.float32) / 255.0
    return torch.from_numpy(np.ascontiguousarray(array)).unsqueeze(0)


class QQPreviewNoBlackBorder:
    """Preview images without ComfyUI's fixed canvas padding and save them."""

    CATEGORY = "QQ/图像"
    FUNCTION = "preview"
    RETURN_TYPES = ("IMAGE",)
    RETURN_NAMES = ("图像",)
    OUTPUT_NODE = True
    DESCRIPTION = "按最长边等比例缩放，保存为 PNG、JPG 或 WebP，并按原始比例预览。"

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "image": ("IMAGE",),
                "保存格式": ([*PREVIEW_FORMATS], {"default": "png"}),
                "最长边": (
                    "INT",
                    {
                        "default": 1024,
                        "min": 0,
                        "max": 16384,
                        "step": 8,
                        "tooltip": "目标最长边像素；设为 0 保持原尺寸。",
                    },
                ),
                "filename_prefix": (
                    "STRING",
                    {"default": "QQPreview", "multiline": False},
                ),
            },
            "hidden": {"prompt": "PROMPT", "extra_pnginfo": "EXTRA_PNGINFO"},
        }

    @staticmethod
    def preview(
        image: torch.Tensor,
        保存格式: str = "png",
        最长边: int = 1024,
        filename_prefix: str = "QQPreview",
        prompt: Any = None,
        extra_pnginfo: Any = None,
    ):
        if not isinstance(image, torch.Tensor) or image.ndim != 4 or image.shape[0] == 0:
            raise ValueError("输入必须是非空 IMAGE 批次")

        image_format = str(保存格式 or "png").lower().lstrip(".")
        if image_format not in PREVIEW_FORMATS:
            raise ValueError(f"不支持的保存格式：{保存格式}")

        prepared: list[torch.Tensor] = []
        pil_images: list[Image.Image] = []
        for frame in image:
            output = _preview_resize(_preview_image_to_pil(frame), int(最长边))
            pil_images.append(output)
            prepared.append(_preview_pil_to_tensor(output))
        output_images = torch.cat(prepared, dim=0)

        height, width = output_images.shape[1:3]
        output_folder, filename, counter, subfolder, _ = folder_paths.get_save_image_path(
            filename_prefix or "QQPreview",
            folder_paths.get_output_directory(),
            width,
            height,
        )
        os.makedirs(output_folder, exist_ok=True)
        results = []
        for batch_number, pil_image in enumerate(pil_images):
            output_name = f"{filename.replace('%batch_num%', str(batch_number))}_{counter:05}_.{image_format}"
            output_path = os.path.join(output_folder, output_name)
            save_image = pil_image.convert("RGB") if image_format == "jpg" else pil_image
            save_kwargs = {}
            if image_format == "jpg":
                save_kwargs = {"quality": 95, "subsampling": 0}
            elif image_format == "webp":
                save_kwargs = {"quality": 95, "method": 4}
            pil_format = "JPEG" if image_format == "jpg" else image_format.upper()
            save_image.save(output_path, format=pil_format, **save_kwargs)
            results.append({"filename": output_name, "subfolder": subfolder, "type": "output"})
            counter += 1

        return {"ui": {"images": results}, "result": (output_images,)}


NODE_CLASS_MAPPINGS = {"QQPreviewNoBlackBorder": QQPreviewNoBlackBorder}
NODE_DISPLAY_NAME_MAPPINGS = {"QQPreviewNoBlackBorder": "QQ-无黑边快速预览"}

